"""Customer migration guide to 0.1.0-preview.5, in Chinese and English."""
from build import table
from customer_layout import code, filename


def migration_sections(locale='zh'):
    t = lambda en, zh: zh if locale == 'zh' else en
    p = lambda en, zh: '<p>' + t(en, zh) + '</p>'
    c = lambda text, language='ts': code(text, language, locale)
    link = lambda page, anchor='': filename(page, locale) + ('#' + anchor if anchor else '')
    section = lambda key, en, zh, body: (key, t(en, zh), body)
    before = lambda: '<p><strong>' + t('Before', '之前') + '</strong></p>'
    after = lambda: '<p><strong>' + t('Now', '现在') + '</strong></p>'

    return [
        section('overview', 'What changes', '变化概览',
            p('preview.5 makes Scripts, Storyboards and Prompts come only from the writers, so every change goes through the same checks, and lets shots use any image, video or audio file. Upgrade from <code>0.1.0-preview.4</code> with the steps below; from <code>0.1.0-preview.3</code>, first do <a href="#from-preview3">the preview.4 steps</a>.',
                'preview.5 让脚本、分镜和提示词只由编写服务生成，因此所有修改都经过相同检查；镜头还可以使用任意图片、视频或音频文件。从 <code>0.1.0-preview.4</code> 升级请按以下步骤操作；从 <code>0.1.0-preview.3</code> 升级请先完成<a href="#from-preview3">升级到 preview.4 的步骤</a>。')
            + p('The new SDK needs the new services: use it once they are released. It sends <code>Nuva-Api-Version: 2026-11-07</code> with every request (you do not set it) and reads the new Product fields, which older services do not have.',
                '新 SDK 需要新版服务，请在服务发布后使用。它在每个请求中发送 <code>Nuva-Api-Version: 2026-11-07</code>（无需自行设置），并读取旧版服务没有的新产品字段。')
            + c('pnpm add /path/to/nuva-sdk-0.1.0-preview.5.tgz', 'sh')),
        section('removed', 'Removed and changed calls', '移除和变更的调用',
            p('Change each call in the left column. TypeScript flags the removed methods after the upgrade; the old <code>scripts.generate({base})</code> and <code>storyboards.generate({base})</code> / <code>({content})</code> forms throw <code>INVALID_INPUT</code> naming the new method before anything is sent.',
                '逐一修改左列中的调用。升级后 TypeScript 会标出已移除的方法；旧的 <code>scripts.generate({base})</code> 和 <code>storyboards.generate({base})</code> / <code>({content})</code> 写法会在发送前抛出 <code>INVALID_INPUT</code>，并给出新方法名。')
            + table([t('preview.4', 'preview.4'), t('preview.5', 'preview.5')], [
                ['<code>prompts.create({data})</code>', t('<code>videos.generate({input: {schema_version: 1, data}})</code>, or change the Storyboard and run <code>prompts.generate</code> again', '<code>videos.generate({input: {schema_version: 1, data}})</code>，或修改分镜后重新调用 <code>prompts.generate</code>')],
                ['<code>prompts.update(ref, {data})</code>', t('<code>prompts.createFrom(base, changes)</code>, with only the render fields you change (<code>prompt</code>, <code>image_asset_ids</code>, <code>video_asset_ids</code>, <code>audio_asset_ids</code>, <code>seconds</code>, <code>ratio</code>)', '<code>prompts.createFrom(base, changes)</code>，只传要修改的渲染字段（<code>prompt</code>、<code>image_asset_ids</code>、<code>video_asset_ids</code>、<code>audio_asset_ids</code>、<code>seconds</code>、<code>ratio</code>）')],
                ['<code>scripts.create({content})</code>', t('<code>scripts.generate</code>, then <code>scripts.generateFrom</code> or <code>scripts.createFrom</code>', '<code>scripts.generate</code>，再用 <code>scripts.generateFrom</code> 或 <code>scripts.createFrom</code>')],
                ['<code>scripts.generate({product, base, …, instruction})</code>', '<code>scripts.generateFrom(base, {instruction, acceptable_duration_ms?})</code>'],
                ['<code>scripts.update(ref, {content, batch_id?})</code>', t('<code>scripts.createFrom(base, changes)</code>, with only the top-level fields you change; it keeps the base\'s Batch', '<code>scripts.createFrom(base, changes)</code>，只传要修改的顶层字段；沿用原脚本的 Batch')],
                ['<code>storyboards.generate({base, instruction, cast?})</code>', '<code>storyboards.generateFrom(base, {instruction, cast?})</code>'],
                ['<code>storyboards.generate({base, content})</code>', '<code>storyboards.createFrom(base, changes)</code>'],
                ['<code>storyboards.generate({content})</code>', t('<code>storyboards.generate({script})</code>, then <code>storyboards.createFrom</code>', '<code>storyboards.generate({script})</code>，再用 <code>storyboards.createFrom</code>')],
                ['<code>NuvaError</code>, <code>NuvaErrorInfo</code>, <code>NuvaErrorCode</code>', '<code>AdsError</code>, <code>AdsErrorInfo</code>, <code>AdsErrorCode</code>'],
                ['<code>APIError.Acceptance</code> (Go)', t('<code>APIError.Retryable</code>: every Admin write repeats to the same result, so a retryable error can be sent again.', '<code>APIError.Retryable</code>：每个 Admin 写入重复执行的结果都相同，因此可重试的错误可以再次发送。')],
                ['<code>error.acceptance</code>', t('<code>error.retryable</code>: when it is true, retry; a write with the same <code>idempotencyKey</code>, which is always safe. The SDK makes a key for every write and retries a dropped connection itself.',
                                                   '<code>error.retryable</code>：为 true 时重试；写入使用相同的 <code>idempotencyKey</code>，这样做始终安全。SDK 会为每个写入生成 key，并自行重试中断的连接。')],
                ['<code>PartialCreationError</code>, <code>error.saved.prompts</code>', t('<code>prompts.generate</code> returns every clip\'s Prompt or an error: call it again (the clips already compiled are reused), or compile one <code>clip</code> at a time.',
                                                                                            '<code>prompts.generate</code> 要么返回所有片段的提示词，要么返回错误：再次调用即可（已编译的片段会被复用），或用 <code>clip</code> 逐个编译。')],
                ['<code>BackendPage&lt;T&gt;</code>, <code>page.next_cursor</code>', t('<code>Page&lt;T&gt;</code>: <code>{items, nextCursor}</code>. Read <code>nextCursor</code>.', '<code>Page&lt;T&gt;</code>：<code>{items, nextCursor}</code>。请读取 <code>nextCursor</code>。')],
                ['<code>skills.version(id, n)</code>, <code>SkillDetail.main</code>, <code>SkillOut</code>, <code>SkillVersionOut</code>', t('<code>skills.get(id, {version: n})</code>. A <code>Skill</code> is one version, the latest by default; <code>main_version</code> names the one new work uses.', '<code>skills.get(id, {version: n})</code>。一个 <code>Skill</code> 是一个版本，默认最新；<code>main_version</code> 是新工作使用的版本。')],
                ['<code>BatchSummary</code> from <code>batches.list</code>', t('<code>Batch</code>, with <code>ads</code> and <code>jobs</code>, as <code>batches.get</code> reads it.', '<code>Batch</code>，带有 <code>ads</code> 和 <code>jobs</code>，与 <code>batches.get</code> 读取的相同。')],
                ['<code>artifact.relationships</code>, <code>artifact.skills</code>', t('Named fields: a Script\'s <code>product</code> and <code>skill</code>; a Storyboard\'s <code>script</code>, <code>product</code>, <code>characters</code> and <code>skill</code>; a Prompt\'s <code>storyboard</code> and <code>skill</code>.', '具名字段：脚本的 <code>product</code> 和 <code>skill</code>；分镜的 <code>script</code>、<code>product</code>、<code>characters</code> 和 <code>skill</code>；提示词的 <code>storyboard</code> 和 <code>skill</code>。')],
                ['<code>artifact.schemaVersion</code>', '<code>artifact.schema_version</code>'],
                ['<code>onTrace</code>, <code>onWireTrace</code>', t('Removed. When you report a problem, send the error\'s <code>requestId</code> and <code>method</code>.', '已移除。反馈问题时，请附上错误的 <code>requestId</code> 和 <code>method</code>。')],
                ['<code>artifacts.get</code> / <code>forSchema</code> / <code>create</code> / <code>update</code>', t('The kind\'s own client: <code>scripts.get</code>, <code>storyboards.get</code>, <code>prompts.get</code>', '使用对应类型的客户端：<code>scripts.get</code>、<code>storyboards.get</code>、<code>prompts.get</code>')],
            ])
            + p('Your own Prompt text: <code>prompts.create</code> is gone; send the same data as raw input.', '自己编写的提示词：<code>prompts.create</code> 已移除，请以原始输入提交相同数据。')
            + before() + c("const prompt = await nuva.prompts.create({ data: { prompt: text, image_asset_ids: [imageId], seconds: 5, ratio: '9:16' } });\nconst job = await nuva.videos.generate({ prompt: prompt.id });")
            + after() + c("const job = await nuva.videos.generate({\n  input: { schema_version: 1, data: { prompt: text, image_asset_ids: [imageId], seconds: 5, ratio: '9:16' } },\n});\n// job.prompt is the Prompt the backend saved for it.")
            + p('Changing a Script: have the writer change it, or save your edit.', '修改脚本：由编写服务修改，或保存自己的编辑。')
            + before() + c("const revised = await nuva.scripts.generate({ product: productId, base: script.id, acceptable_duration_ms: range, instruction: '开头更短' });\nconst edited = await nuva.scripts.update(script.ref, { content, batch_id: batchId });")
            + after() + c("const revised = await nuva.scripts.generateFrom(script.ref, { instruction: '开头更短' }); // keeps the length without a range\nconst edited = await nuva.scripts.createFrom(script.ref, { panels }); // only the fields you change")
            + p('Changing a Storyboard:', '修改分镜：')
            + before() + c("await nuva.storyboards.generate({ base: storyboard.id, instruction: '第二个片段换成特写' });\nawait nuva.storyboards.generate({ base: storyboard.id, content });")
            + after() + c("await nuva.storyboards.generateFrom(storyboard.ref, { instruction: '第二个片段换成特写' });\nawait nuva.storyboards.createFrom(storyboard.ref, { clips });")
            + p('A Script saved before Storyboards (<code>format: 2</code>) is read-only: <code>scripts.generateFrom</code> and <code>scripts.createFrom</code> on it throw <code>INVALID_INPUT</code> before anything is sent. Write a new Script with <code>scripts.generate</code>.',
                'Storyboard 推出之前保存的脚本（<code>format: 2</code>）为只读：对其调用 <code>scripts.generateFrom</code> 或 <code>scripts.createFrom</code> 会在发送前抛出 <code>INVALID_INPUT</code>。请用 <code>scripts.generate</code> 生成新脚本。')),
        section('entities', 'Brands, Products and Characters', '品牌、产品和人物',
            p('<code>update</code> takes the record you read (or <code>{id, version}</code>) and only the fields you change. Product media fields have new names, and <code>uploadImage</code> is gone: upload the file, then add its ID.',
                '<code>update</code> 接收读取到的记录（或 <code>{id, version}</code>），只传要修改的字段。产品的媒体字段已改名，<code>uploadImage</code> 已移除：先上传文件，再加入其 ID。')
            + table([t('preview.4', 'preview.4'), t('preview.5', 'preview.5')], [
                ['<code>update({base, brand_id, data})</code>', t('<code>update(record, {data?, brand_id?})</code>: <code>data</code> holds only the fields to change. A list is replaced as a whole, <code>null</code> clears an optional value, and a newer version saved since is <code>REVISION_CONFLICT</code>.', '<code>update(record, {data?, brand_id?})</code>：<code>data</code> 只包含要修改的字段。列表整体替换，<code>null</code> 清除可选值；读取后已有更新的版本时返回 <code>REVISION_CONFLICT</code>。')],
                ['<code>data.images</code> / <code>data.videos</code>', '<code>data.image_asset_ids</code> / <code>data.video_asset_ids</code>'],
                ['<code>products.uploadImage({base, file})</code>, <code>ProductImageUploadError</code>', t('<code>assets.upload(file, {kind: \'image\', label})</code>, then <code>products.update</code>. If the update fails, retry it with the same Asset ID.', '<code>assets.upload(file, {kind: \'image\', label})</code>，再调用 <code>products.update</code>。更新失败时，用同一个 Asset ID 重试。')],
                ['<code>assets.uploadIntent</code> / <code>assets.register</code>', '<code>assets.upload(file)</code> / <code>assets.upload({url})</code>'],
                ['<code>revision</code>', t('Gone: the version you read is <code>version</code>, and a reference is <code>{id, version}</code>.', '已移除：读取到的版本为 <code>version</code>，引用为 <code>{id, version}</code>。')],
            ])
            + before() + c("const uploaded = await nuva.products.uploadImage({ base: product, file });\nconst saved = await nuva.products.update({ base: uploaded.product, brand_id: product.brand_id, data: { ...uploaded.product.data, name } });")
            + after() + c("const image = await nuva.assets.upload(file, { kind: 'image', label: 'Box, front' });\nconst saved = await nuva.products.update(product, {\n  data: { name, image_asset_ids: [...(product.data.image_asset_ids ?? []), image.id] },\n});")),
        section('named-files', 'Prompts must name every file', '提示词必须提到每个文件',
            p('A Prompt\'s text names its files by position: <code>&lt;Picture 1&gt;</code> is the first of <code>image_asset_ids</code>, and likewise <code>&lt;Video N&gt;</code> and <code>&lt;Audio N&gt;</code>. The video model ignores a file the text does not name. A new Prompt (<code>videos.generate({input})</code>, <code>prompts.createFrom</code>) must name every attached file, and no number past the end of its list; otherwise it is rejected with <code>422 INVALID_PROMPT</code>, nothing is saved or charged, and the message says which file is missing.',
                '提示词按位置指代文件：<code>&lt;Picture 1&gt;</code> 是 <code>image_asset_ids</code> 中的第一个，<code>&lt;Video N&gt;</code> 和 <code>&lt;Audio N&gt;</code> 同理。视频模型会忽略文字中没有提到的文件。新的提示词（<code>videos.generate({input})</code>、<code>prompts.createFrom</code>）必须提到每个附带的文件，且编号不能超出列表；否则返回 <code>422 INVALID_PROMPT</code>，不会保存或计费，错误信息会指出缺少哪个文件。')
            + before() + c("// Accepted, but the video model ignored the second image.\ndata: { prompt: 'Show <Picture 1> on a table.', image_asset_ids: [product, poster] }")
            + after() + c("data: { prompt: 'Show <Picture 1> on a table, with the poster in <Picture 2> on the wall.', image_asset_ids: [product, poster] }")
            + p('Prompts from <code>prompts.generate</code> always name their files. To change what gets rendered, change the Storyboard or the Product and compile again: see <a href="' + link('generation', 'change-render') + '">Change what gets rendered</a>.',
                '<code>prompts.generate</code> 生成的提示词总会提到其文件。需要修改生成内容时，请修改分镜或产品后重新编译，见<a href="' + link('generation', 'change-render') + '">修改生成的内容</a>。')),
        section('also-new', 'Also new', '其他变化',
            table([t('Change', '变化'), t('What to know', '说明')], [
                [t('File tokens', '文件标记'), t('<code>{{asset:&lt;id&gt;}}</code> uses any image, video or audio Asset you may use; <code>{{role:&lt;id&gt;}}</code> and <code>{{product:&lt;id&gt;}}</code> take any file that Character or Product has. The file\'s kind decides how it is used. They work in shots and in <code>instruction</code>; see <a href="' + link('generation', 'tokens') + '">Tokens in shots</a>.', '<code>{{asset:&lt;id&gt;}}</code> 可使用你有权使用的任意图片、视频或音频 Asset；<code>{{role:&lt;id&gt;}}</code> 和 <code>{{product:&lt;id&gt;}}</code> 可使用该人物或产品的任意文件。文件类型决定其用法。可写在镜头和 <code>instruction</code> 中，见<a href="' + link('generation', 'tokens') + '">镜头中的标记</a>。')],
                [t('Product videos', '产品视频'), t('Products take up to 5 <code>video_asset_ids</code>. While anyone in your organization still reads Products with preview.4 or older, don\'t add videos: those SDKs can\'t read a Product that has them, and <code>products.list</code> then fails for the whole page.', '产品可保存最多 5 个 <code>video_asset_ids</code>。组织中仍有人用 preview.4 或更早版本读取产品时，请不要添加视频：这些版本无法读取带视频的产品，<code>products.list</code> 会因此整页失败。')],
                [t('Brand and Product descriptions', '品牌和产品描述'), t('Brands take a <code>description</code> (up to 5,000 characters) and <code>attributes</code> (JSON), and Products a <code>description</code>; the Script writer reads them as context. Like Product videos: while anyone in your organization still reads Brands or Products with preview.4, don\'t set them; those SDKs can\'t read a record that has them.', '品牌新增 <code>description</code>（最多 5,000 个字符）和 <code>attributes</code>（JSON），产品新增 <code>description</code>；脚本编写服务会将其作为背景信息读取。与产品视频相同：组织中仍有人用 preview.4 读取品牌或产品时，请不要设置；这些版本无法读取带有这些字段的记录。')],
                [t('Steering', '插话'), t('<code>agent.send</code> no longer gets <code>AGENT_BUSY</code> while the Agent works: the message shows at once with <code>unread: true</code> and joins at the Agent\'s next step.', 'Agent 工作时 <code>agent.send</code> 不再返回 <code>AGENT_BUSY</code>：消息立即显示并带有 <code>unread: true</code>，在 Agent 的下一步加入对话。')],
                [t('Deleting Products', '删除产品'), t('<code>products.delete(id)</code>. What was made from the Product stays readable, and its saved Prompts still render.', '<code>products.delete(id)</code>。由该产品生成的内容仍可读取，已保存的提示词仍可生成视频。')],
                [t('Who may change what', '修改权限'), t('Brands, Products and Characters saved before this release stay editable by everyone in your organization, as before; deleting or sharing them takes an admin of <code>customer</code>. New ones belong to the user who makes them. See the CHANGELOG\'s "Who sees what".', '本版本之前保存的品牌、产品和人物，组织内所有人仍可编辑，与之前相同；删除或共享它们需要 <code>customer</code> 的管理员。新建的品牌、产品和人物归创建者所有。详见 CHANGELOG 中的 “Who sees what”。')],
                [t('Cancelling Jobs', '取消任务'), t('<code>jobs.cancel(id)</code> stops a queued or running Job; it ends <code>cancelled</code>. A finished Job returns <code>JOB_FINISHED</code>.', '<code>jobs.cancel(id)</code> 停止排队中或运行中的任务，任务以 <code>cancelled</code> 结束；已完成的任务返回 <code>JOB_FINISHED</code>。')],
                [t('Raw video input', '原始视频输入'), t('<code>videos.generate({input})</code> data takes only <code>prompt</code>, <code>image_asset_ids</code>, <code>video_asset_ids</code>, <code>audio_asset_ids</code>, <code>seconds</code> and <code>ratio</code>: no <code>characters</code>, <code>clip_id</code> or <code>relationships</code>. Without <code>seed</code> each Job gets a random one, returned as <code>job.seed</code>.', '<code>videos.generate({input})</code> 的 data 只接受 <code>prompt</code>、<code>image_asset_ids</code>、<code>video_asset_ids</code>、<code>audio_asset_ids</code>、<code>seconds</code> 和 <code>ratio</code>，不再接受 <code>characters</code>、<code>clip_id</code> 或 <code>relationships</code>。不传 <code>seed</code> 时每个任务使用随机种子，并通过 <code>job.seed</code> 返回。')],
                [t('Job reads', '任务读取'), t('A failed Job has <code>error_code</code>, for example <code>GENERATION_FAILED</code>. <code>checkpoint</code> is gone.', '失败的任务带有 <code>error_code</code>，例如 <code>GENERATION_FAILED</code>。<code>checkpoint</code> 已移除。')],
                [t('Artifact reads', '产物读取'), t('Scripts, Storyboards and Prompts have no <code>entities</code> map. A relationship to a Product or Character reads <code>{kind, id, version}</code>.', '脚本、分镜和提示词不再有 <code>entities</code>。指向产品或人物的 relationship 读作 <code>{kind, id, version}</code>。')],
                [t('Error codes', '错误码'), t('The backend\'s <code>UNAUTHORIZED</code> is now <code>UNAUTHENTICATED</code>, and <code>INVALID_REQUEST</code> is now <code>INVALID_INPUT</code>, the codes the SDK already used. Check for the new codes.', '后端的 <code>UNAUTHORIZED</code> 改为 <code>UNAUTHENTICATED</code>，<code>INVALID_REQUEST</code> 改为 <code>INVALID_INPUT</code>，与 SDK 已使用的错误码一致。请按新错误码判断。')],
                [t('Attaching an Asset', '附加 Asset'), t('<code>Message.create().attach(asset)</code> compiles under strict TypeScript.', '<code>Message.create().attach(asset)</code> 在 strict TypeScript 下可以编译。')],
            ])),
        section('grace', 'Grace period for existing integrations', '现有集成的过渡期',
            p('If we told you your organization is on the grace list, your preview.4 calls keep working after the release while you upgrade: <code>prompts.create</code>, <code>scripts.create</code>, direct <code>scripts.update</code> and <code>storyboards.generate({content})</code>. A Prompt that leaves a file unnamed is saved as before instead of being rejected; the file is still ignored by the video model.',
                '如果我们已告知你的组织在过渡名单中，发布后你在 preview.4 上的调用仍可使用，方便你逐步升级：<code>prompts.create</code>、<code>scripts.create</code>、直接调用的 <code>scripts.update</code> 和 <code>storyboards.generate({content})</code>。文字中未提到某个文件的提示词仍会照旧保存，不会被拒绝；视频模型仍会忽略该文件。')
            + p('Each such response carries <code>Deprecation: true</code> and a <code>Link</code> to this page; log it to find the calls left to change. The grace period ends later, after we tell you; then these calls get the preview.5 behavior: <code>403</code> for the removed creates and direct versions, <code>422 REJECTED</code> for <code>storyboards.generate({content})</code> without a base, and <code>422 INVALID_PROMPT</code> for a Prompt that leaves a file unnamed. Organizations not on the list get the preview.5 behavior at once.',
                '这类响应带有 <code>Deprecation: true</code> 和指向本页的 <code>Link</code> 头；记录它们即可找出还需修改的调用。过渡期会在我们通知后结束，届时这些调用将按 preview.5 处理：已移除的创建和直接保存版本返回 <code>403</code>，不带 base 的 <code>storyboards.generate({content})</code> 返回 <code>422 REJECTED</code>，未提到所有文件的提示词返回 <code>422 INVALID_PROMPT</code>。不在名单中的组织在发布后立即按 preview.5 处理。')),
        section('from-preview3', 'From preview.3', '从 preview.3 升级',
            p('Since 2026-11-04, Script and Prompt generation needs preview.4 or later. Make these changes first, then the ones above.',
                '自 2026-11-04 起，脚本和提示词生成需要 preview.4 或更高版本。请先完成以下修改，再完成上面的修改。')
            + '<ol>'
            + '<li>' + t('Generation is four steps: <code>scripts.generate</code> → <code>storyboards.generate({script, cast?, instruction?})</code> → <code>prompts.generate({storyboard, ratio})</code> → <code>videos.generate({prompt})</code>. The shooting instruction moves to <code>storyboards.generate</code>; <code>prompts.generate</code> no longer takes <code>script</code>, <code>instruction</code> or <code>batch_id</code>.', '生成流程分四步：<code>scripts.generate</code> → <code>storyboards.generate({script, cast?, instruction?})</code> → <code>prompts.generate({storyboard, ratio})</code> → <code>videos.generate({prompt})</code>。拍摄要求改为传给 <code>storyboards.generate</code>；<code>prompts.generate</code> 不再接受 <code>script</code>、<code>instruction</code> 和 <code>batch_id</code>。') + '</li>'
            + '<li>' + t('Read Scripts by <code>format</code>: <code>3</code> has <code>.content</code>; Scripts saved before 2026-11-04 are <code>2</code>, read-only, with <code>.legacy</code>. Write new Scripts for new work.', '按 <code>format</code> 读取脚本：<code>3</code> 用 <code>.content</code>；2026-11-04 之前保存的脚本为 <code>2</code>，只读，用 <code>.legacy</code>。新的工作请生成新脚本。') + '</li>'
            + '<li>' + t('A Job from a saved Prompt joins its Batch by itself; drop <code>batch_id</code> from <code>videos.generate</code>.', '由已保存提示词创建的任务会自动加入其 Batch；<code>videos.generate</code> 不必再传 <code>batch_id</code>。') + '</li>'
            + '<li>' + t('<code>asset.label</code> is your label or <code>null</code>.', '<code>asset.label</code> 是你设置的标签，未设置时为 <code>null</code>。') + '</li>'
            + '<li>' + t('Allow 300 s for <code>storyboards.generate</code> and <code>prompts.generate</code> if you set <code>requestTimeoutMs</code>.', '如果设置了 <code>requestTimeoutMs</code>，请为 <code>storyboards.generate</code> 和 <code>prompts.generate</code> 留出 300 秒。') + '</li>'
            + '</ol>'),
        section('checklist', 'Checklist', '检查清单',
            '<ul>'
            + '<li>' + t('Install the preview.5 archive (and Go <code>v0.1.0-preview.5</code> if you use the Go Admin SDK).', '安装 preview.5 包（使用 Go Admin SDK 时同时升级到 <code>v0.1.0-preview.5</code>）。') + '</li>'
            + '<li>' + t('Replace <code>prompts.create</code>, <code>prompts.update</code>, <code>scripts.create</code> and the <code>artifacts</code> client.', '替换 <code>prompts.create</code>、<code>prompts.update</code>、<code>scripts.create</code> 和 <code>artifacts</code> 客户端。') + '</li>'
            + '<li>' + t('Use <code>generateFrom</code> and <code>createFrom</code> on <code>scripts</code> and <code>storyboards</code> for changes.', '修改时使用 <code>scripts</code> 和 <code>storyboards</code> 的 <code>generateFrom</code> 与 <code>createFrom</code>。') + '</li>'
            + '<li>' + t('Send only changed fields to Brand, Product and Character <code>update</code>; rename <code>images</code>/<code>videos</code> to <code>image_asset_ids</code>/<code>video_asset_ids</code>; replace <code>uploadImage</code> with <code>assets.upload</code> and <code>update</code>.', '品牌、产品和人物的 <code>update</code> 只传修改的字段；将 <code>images</code>/<code>videos</code> 改为 <code>image_asset_ids</code>/<code>video_asset_ids</code>；用 <code>assets.upload</code> 加 <code>update</code> 替换 <code>uploadImage</code>。') + '</li>'
            + '<li>' + t('Check for <code>UNAUTHENTICATED</code> and <code>INVALID_INPUT</code> instead of <code>UNAUTHORIZED</code> and <code>INVALID_REQUEST</code>.', '用 <code>UNAUTHENTICATED</code> 和 <code>INVALID_INPUT</code> 替代 <code>UNAUTHORIZED</code> 和 <code>INVALID_REQUEST</code> 的判断。') + '</li>'
            + '<li>' + t('Make sure raw Prompt text names every attached file as <code>&lt;Picture N&gt;</code>, <code>&lt;Video N&gt;</code> or <code>&lt;Audio N&gt;</code>, and handle <code>422 INVALID_PROMPT</code>.', '确保原始提示词文字用 <code>&lt;Picture N&gt;</code>、<code>&lt;Video N&gt;</code> 或 <code>&lt;Audio N&gt;</code> 提到每个附带文件，并处理 <code>422 INVALID_PROMPT</code>。') + '</li>'
            + '<li>' + t('On the grace list: watch for <code>Deprecation</code> response headers until none are left.', '在过渡名单中：留意 <code>Deprecation</code> 响应头，直到不再出现。') + '</li>'
            + '</ul>'),
    ]
